CREATE OR REPLACE FUNCTION public.be_dispatch_publish_wayplan_v43(p_wayplan_id text, p_actor_email text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_wayplan text := nullif(btrim(coalesce(p_wayplan_id, '')), '');
  v_actor text := public.be_wayplan_review_actor_v43(p_actor_email);
  v_review_status text;
  v_result jsonb;
begin
  if auth.uid() is null and session_user <> 'postgres' then
    raise exception 'Authenticated Dispatch operator is required';
  end if;
  select review_status into v_review_status
  from public.be_wayplan_review_v43 where wayplan_id = v_wayplan for update;

  if v_review_status = 'DISPATCHED' then
    return jsonb_build_object('ok', true, 'wayplan_id', v_wayplan, 'review_status', 'DISPATCHED', 'already_published', true);
  end if;
  if v_review_status <> 'DISPATCH_READY' then
    raise exception 'Publish blocked. Wayplan % requires Supervisor approval and DISPATCH_READY status. Current status: %', v_wayplan, coalesce(v_review_status, 'NOT_SUBMITTED');
  end if;

  v_result := public.be_dispatch_publish_wayplan_v41(v_wayplan, v_actor);

  update public.be_wayplan_review_v43
  set review_status = 'DISPATCHED', dispatched_at = now(), updated_at = now()
  where wayplan_id = v_wayplan;

  insert into public.be_wayplan_review_events_v43(wayplan_id, event_type, actor_email, actor_role, payload)
  values (v_wayplan, 'SUPERVISOR_APPROVED_WAYPLAN_PUBLISHED', v_actor, public.be_wayplan_review_role_v43(), coalesce(v_result, '{}'::jsonb));

  return coalesce(v_result, '{}'::jsonb) || jsonb_build_object(
    'ok', true,
    'wayplan_id', v_wayplan,
    'review_status', 'DISPATCHED',
    'supervisor_approval_enforced', true
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.be_wayplan_can_review_v43()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
declare
  v_role text := regexp_replace(public.be_wayplan_review_role_v43(), '[^a-z0-9]+', '', 'g');
  v_super boolean := false;
begin
  if session_user = 'postgres' then return true; end if;

  begin
    v_super := public.be_is_super_admin_v39();
  exception when others then
    v_super := false;
  end;

  return coalesce(v_super,false) or v_role in (
    'superadmin','systemadmin','appowner','admin','administrator',
    'supervisor','operationssupervisor',
    'operationmanager','operationsmanager','opsmanager','operationsadmin',
    'management','director',
    'branchadmin','branchmanager','dispatchsupervisor'
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.be_wayplan_region_set_active_v19(p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
declare
  v_region text := upper(nullif(btrim(coalesce(p_payload->>'region_code','')),''));
  v_active boolean := lower(coalesce(p_payload->>'is_active','false')) in ('true','1','yes','on');
  v_reason text := nullif(btrim(coalesce(p_payload->>'reason','')),'');
  v_role text := lower(replace(coalesce(public.be_current_user_role(),''),'-','_'));
  v_profile_role text := lower(replace(coalesce(public.be_current_role(),''),'-','_'));
  v_row public.be_wayplan_region_runtime_v19;
begin
  if auth.uid() is null then raise exception 'Authentication is required.'; end if;
  if v_role not in (
       'app_owner','super_admin','superadmin','admin','operations_admin','operations',
       'operation_manager','operations_manager','ops_manager','supervisor','wayplan_manager','dispatch'
     )
     and v_profile_role not in (
       'app_owner','super_admin','superadmin','admin','operations_admin','operations',
       'operation_manager','operations_manager','ops_manager','supervisor','wayplan_manager','dispatch'
     ) then
    raise exception 'Wayplan region management permission is required.';
  end if;
  if v_region not in ('YANGON','MANDALAY','NAYPYITAW') then
    raise exception 'Choose Yangon, Mandalay, or Naypyitaw.';
  end if;
  if length(coalesce(v_reason,''))<5 then
    raise exception 'A change reason of at least 5 characters is required.';
  end if;

  update public.be_wayplan_region_runtime_v19
  set is_active=v_active,updated_at=now(),updated_by=auth.uid(),change_reason=v_reason
  where region_code=v_region
  returning * into v_row;

  insert into public.be_audit_events(
    actor_id,actor_email,actor_role,action,resource_type,resource_id,details,
    upload_code,event_type,entity_type,entity_id,payload
  ) values (
    auth.uid(),lower(auth.jwt()->>'email'),coalesce(nullif(v_role,'guest'),nullif(v_profile_role,''),'unknown'),
    'WAYPLAN_REGION_ACTIVE_CHANGED','WAYPLAN_REGION',v_region,
    jsonb_build_object('is_active',v_active,'reason',v_reason),
    'WAYPLAN_REGION_CONTROL_V19_20260903','WAYPLAN_REGION_ACTIVE_CHANGED',
    'WAYPLAN_REGION',v_region,jsonb_build_object('region',to_jsonb(v_row))
  );

  return jsonb_build_object('ok',true,'region',to_jsonb(v_row),'build','WAYPLAN_REGION_CONTROL_V19_20260903');
end
$function$
